module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic [31:0] in,
    output logic [31:0] out
);

    // Internal register to store the previous cycle's input value for each bit
    logic [31:0] prev_in;

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous active-high reset: clear output and history
            prev_in <= 32'b0;
            out     <= 32'b0;
        end else begin
            // Capture the current input as the previous input for the next cycle
            prev_in <= in;

            // Detect falling edge (1 -> 0) for each bit.
            // If a falling edge is detected, the corresponding output bit is set to 1.
            // The bitwise OR with the current 'out' value ensures the output remains 1
            // (latched) until a synchronous reset occurs.
            out <= out | (~in & prev_in);
        end
    end

endmodule

