module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic x,
    output logic z
);

// One-hot state encoding: state_A = 1 means state A, state_B = 1 means state B
logic state_A, state_B;

// Next-state signals (one-hot maintained)
logic next_A, next_B;

// Combinational next-state logic
// From A: x=0 → stay A, x=1 → go to B
// From B: x=0 → stay B, x=1 → stay B
assign next_A = state_A & ~x;       // stays A if x=0; becomes 0 if in B or x=1
assign next_B = (state_A & x) | state_B;  // goes to B from A if x=1; stays B always

// Mealy output: z depends on current state and input x
assign z = (state_A & x) | (state_B & ~x);

// Synchronous state flip-flops with asynchronous active-high reset
// Reset forces the machine into state A (state_A=1, state_B=0)
always @(posedge clk or posedge areset) begin
    if (areset) begin
        state_A <= 1'b1;
        state_B <= 1'b0;
    end else begin
        state_A <= next_A;
        state_B <= next_B;
    end
end

endmodule

