reg s;

// Next‑state logic (Moore machine: next state depends only on current state and input)
// From B (s=1): in=0 → A (s=0), in=1 → B (s=1)
// From A (s=0): in=0 → B (s=1), in=1 → A (s=0)
// next_s = (s & in) | (~s & ~in)  which is XNOR
wire next_s;
assign next_s = (s & in) | (~s & ~in);

// State flip‑flop with asynchronous active‑high reset to state B
