    input  logic areset,
    input  logic bump_left,
    input  logic bump_right,
    input  logic ground,
    output logic walk_left,
    output logic walk_right,
    output logic aaah
);

// State encoding:
 // 2'b00 : WalkLeft
 // 2'b01 : WalkRight
 // 2'b10 : FallingLeft
 // 2'b11 : FallingRight

reg [1:0] state;

always @(posedge clk or posedge areset) begin
    if (areset)
        state <= 2'b00;          // asynchronous reset to WalkLeft
    else
        case (state)
            2'b00: // WalkLeft
                if (ground)
                    state <= (bump_left | bump_right) ? 2'b01 : 2'b00; // bump flips direction
                else
                    state <= 2'b10; // fall down

            2'b01: // WalkRight
                if (ground)
                    state <= (bump_left | bump_right) ? 2'b00 : 2'b01; // bump flips direction
                else
                    state <= 2'b11; // fall down

            2'b10: // FallingLeft
                if (ground)
                    state <= 2'b00; // ground reappears, resume walking left
                else
                    state <= 2'b10; // stay falling

            2'b11: // FallingRight
                if (ground)
                    state <= 2'b01; // ground reappears, resume walking right
                else
                    state <= 2'b11; // stay falling
        endcase
end

// Moore output logic: outputs depend only on current state
always @(*) begin
    walk_left  = (state == 2'b00);
    walk_right = (state == 2'b01);
    aaah       = (state == 2'b10 || state == 2'b11);
end

endmodule

