module TopModule(
    input  logic clk,
    input  logic load,
    input  logic [255:0] data,
    output logic [255:0] q
);
    logic [255:0] nq;

    // Sequential logic: positive-edge-triggered flip-flop
    always_ff @(posedge clk) begin
        if (load)
            q <= data;          // load initial state
        else
            q <= nq;            // advance one Game of Life step
    end

    // Combinational logic: compute next state from current state
    always_comb begin
        nq = 256'd0;
        for (int r = 0; r < 16; r++) begin
            for (int c = 0; c < 16; c++) begin
                int i = r * 16 + c;          // bit index for cell (r,c)
                int count = 0;                // number of live neighbours

                // North
                count += q[((r - 1 + 16) % 16) * 16 + c];
                // South
                count += q[((r + 1) % 16) * 16 + c];
                // East
                count += q[r * 16 + ((c + 1) % 16)];
                // West
                count += q[r * 16 + ((c - 1 + 16) % 16)];
                // Northeast
                count += q[((r - 1 + 16) % 16) * 16 + ((c + 1) % 16)];
                // Northwest
                count += q[((r - 1 + 16) % 16) * 16 + ((c - 1 + 16) % 16)];
                // Southeast
                count += q[((r + 1) % 16) * 16 + ((c + 1) % 16)];
                // Southwest
                count += q[((r + 1) % 16) * 16 + ((c - 1 + 16) % 16)];

                // Apply Game of Life rules
                if (count <= 1)
                    nq[i] = 1'b0;
                else if (count == 2)
                    nq[i] = q[i];            // stay the same
                else if (count == 3)
                    nq[i] = 1'b1;
                else                          // 4 or more neighbours
                    nq[i] = 1'b0;
            end
        end
    end
endmodule

