module TopModule (
    input clk,
    input reset,
    input data,
    input done_counting,
    input ack,
    output reg shift_ena,
    output reg counting,
    output reg done
);

    // State encoding
    localparam IDLE = 2'b00, SHIFT = 2'b01, COUNT = 2'b10, DONE = 2'b11;

    reg [1:0] state, next_state;
    reg [3:0] ps;   // 4-bit shift register for pattern detection
    reg [1:0] cnt;  // 2-bit counter for 4 clock cycles (0,1,2,3)

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            ps <= 4'b0;
            cnt <= 2'b0;
        end else begin
            // shift in data bit for pattern detection
            ps <= {ps[2:0], data};

            next_state <= state;

            case (state)
                IDLE: begin
                    if (ps == 4'b1101)
                        next_state <= SHIFT;
                    cnt <= 2'b0;
                end
                SHIFT: begin
                    cnt <= cnt + 1;
                    if (cnt == 2'd3)
                        next_state <= COUNT;
                end
                COUNT: begin
                    if (done_counting)
                        next_state <= DONE;
                    cnt <= 2'b0;
                end
                DONE: begin
                    if (ack)
                        next_state <= IDLE;
                    cnt <= 2'b0;
                end
            endcase

            state <= next_state;
        end
    end

    // Output logic
    always @(*) begin
        shift_ena = 1'b0;
        counting = 1'b0;
        done = 1'b0;
        case (state)
            SHIFT: shift_ena = 1'b1;
            COUNT: counting = 1'b1;
            DONE: done = 1'b1;
        endcase
    end

endmodule

