module TopModule (
    input clk,
    input areset,
    input bump_left,
    input bump_right,
    input ground,
    input dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    reg [2:0] state;
    parameter S_WL = 3'b000; // walk left on ground
    parameter S_WR = 3'b001; // walk right on ground
    parameter S_FL = 3'b010; // fall, resume left
    parameter S_FR = 3'b011; // fall, resume right
    parameter S_DL = 3'b100; // dig, resume left
    parameter S_DR = 3'b101; // dig, resume right

    // Moore outputs
    assign walk_left = (state == S_WL);
    assign walk_right = (state == S_WR);
    assign aaah = (state == S_FL) | (state == S_FR);
    assign digging = (state == S_DL) | (state == S_DR);

    // Next-state logic (positive edge triggered, async reset)
    always @(posedge clk) begin
        if (areset) begin
            state <= S_WL;
        end else begin
            case (state)
                S_WL: begin
                    if (~ground) state <= S_FL;
                    else if (dig) state <= S_DL;
                    else if (bump_left | bump_right) begin
                        if (bump_left) state <= S_WR;
                        else state <= S_WL;
                    end else begin
                        state <= S_WL;
                    end
                end
                S_WR: begin
                    if (~ground) state <= S_FR;
                    else if (dig) state <= S_DR;
                    else if (bump_left | bump_right) begin
                        if (bump_right) state <= S_WL;
                        else state <= S_WR;
                    end else begin
                        state <= S_WR;
                    end
                end
                S_FL: begin
                    if (ground) state <= S_WL;
                    else state <= S_FL;
                end
                S_FR: begin
                    if (ground) state <= S_WR;
                    else state <= S_FR;
                end
                S_DL: begin
                    if (~ground) state <= S_FL;
                    else if (!dig) state <= S_WL;
                    else state <= S_DL;
                end
                S_DR: begin
                    if (~ground) state <= S_FR;
                    else if (!dig) state <= S_WR;
                    else state <= S_DR;
                end
                default: state <= S_WL;
            endcase
        end
    end

endmodule

