module TopModule (
    input clk,
    input load,
    input [511:0] data,
    output [511:0] q
);

    // Current state of the 512-cell cellular automaton
    reg [511:0] q_reg;

    // Next state computed by Rule 90
    wire [511:0] next_q;

    // Boundary-aware neighbor signals (left and right for all 512 cells)
    wire [511:0] left_n, right_n;

    // Generate 512 cells implementing Rule 90
    genvar i;
    generate
        for (i = 0; i < 512; i = i + 1) begin: cell
            // Left neighbour: q_reg[i-1] for i>0, else 0 (boundary)
            assign left_n[i] = (i == 0) ? 1'b0 : q_reg[i-1];

            // Right neighbour: q_reg[i+1] for i<511, else 0 (boundary)
            assign right_n[i] = (i == 511) ? 1'b0 : q_reg[i+1];

            // Next state is XOR of the two neighbours
            assign next_q[i] = left_n[i] ^ right_n[i];
        end
    endgenerate

    // Sequential update on the positive edge of the clock
    always @(posedge clk) begin
        if (load)
            q_reg <= data;          // Load the provided data
        else
            q_reg <= next_q;        // Advance one time step by Rule 90
    end

    // Output assignment
    assign q = q_reg;

endmodule

