module TopModule (
    input  clk,
    input  load,
    input  [511:0] data,
    output [511:0] q
);

    // Internal register to hold the current state of the 512-cell CA
    reg [511:0] q_reg;
    // Internal register for the next state
    reg [511:0] q_next;

    // Sequential logic: triggered on the positive edge of the clock
    always @(posedge clk) begin
        if (load) begin
            // Synchronous active-high load: replace state with input data
            q_reg <= data;
        end else begin
            // Otherwise, advance the cellular automaton by one time step
            q_reg <= q_next;
        end
    end

    // Output assignment
    assign q = q_reg;

    // Rule 110 Next-State Logic
    // A generate block is used to instantiate the next-state calculation for each of the 512 cells.
    genvar i;
    always @* begin : rule110_next_state
        for (i = 0; i < 512; i = i + 1) begin : cell_loop
            // Determine the left and right neighbors.
            // Boundaries (q[-1] and q[512]) are assumed to be 0 (off).
            // Left neighbor: q_reg[i-1] if i > 0, else 1'b0
            // Right neighbor: q_reg[i+1] if i < 511, else 1'b0
            // Center: q_reg[i]

            // Case statement implements the Rule 110 lookup table.
            // Table: Left | Center | Right | Next State
            // 111 -> 0
            // 110 -> 1
            // 101 -> 1
            // 100 -> 0
            // 011 -> 1
            // 010 -> 1
            // 001 -> 1
            // 000 -> 0
            case ({ (i == 0) ? 1'b0 : q_reg[i-1], q_reg[i], (i == 511) ? 1'b0 : q_reg[i+1] })
                3'b000: q_next[i] <= 1'b0;
                3'b001: q_next[i] <= 1'b1;
                3'b010: q_next[i] <= 1'b1;
                3'b011: q_next[i] <= 1'b1;
                3'b100: q_next[i] <= 1'b0;
                3'b101: q_next[i] <= 1'b1;
                3'b110: q_next[i] <= 1'b1;
                3'b111: q_next[i] <= 1'b0;
            endcase
        end
    end

endmodule

